#!/usr/bin/env python3
"""Exact, visually transcribed solutions for Peterson grade 6 part 1, 340–497.

The published condition/drawing remains the verified textbook image. This file
builds flat answer parts and independently evaluates arithmetic trees with
fractions.Fraction; it does not access learner data or make network requests.
"""
from pathlib import Path
from fractions import Fraction as F
import ast
import json
import re

ROOT = Path(__file__).resolve().parents[1]
OUT = ROOT / 'school/peterson6/textbook/content/340-497.json'
EX = {}
PAGES = {}
for lo, hi, page in [(340,344,81),(345,350,82),(351,358,86),(359,366,87),
 (367,375,88),(376,380,89),(381,386,90),(387,392,91),(393,396,92),
 (397,402,93),(403,406,94),(407,414,95),(415,423,96),(424,426,97),
 (427,435,100),(436,441,101),(442,446,102),(447,452,103),(453,458,104),
 (459,461,105),(462,465,107),(466,474,108),(475,487,109),(488,497,110)]:
    for number in range(lo, hi + 1): PAGES[number] = page

def rat(value):
    if isinstance(value, F): return value
    value = str(value).replace(',', '.').strip()
    if ' ' in value:
        whole, fraction = value.split()
        return F(whole) + (F(fraction) if F(whole) >= 0 else -F(fraction))
    return F(value)

def s(value):
    value = rat(value)
    return str(value.numerator) if value.denominator == 1 else f'{value.numerator}/{value.denominator}'

OPS = {ast.Add:'add', ast.Sub:'subtract', ast.Mult:'multiply', ast.Div:'divide'}
def tree(text):
    def walk(node):
        if isinstance(node, ast.Constant) and isinstance(node.value, (int, float)):
            return ast.get_source_segment(text, node)
        if isinstance(node, ast.Call) and isinstance(node.func, ast.Name) and node.func.id == 'q':
            assert len(node.args) == 1 and isinstance(node.args[0], ast.Constant)
            rat(node.args[0].value)
            return node.args[0].value
        if isinstance(node, ast.UnaryOp) and isinstance(node.op, ast.USub):
            return {'op':'subtract','left':'0','right':walk(node.operand)}
        assert isinstance(node, ast.BinOp) and type(node.op) in OPS, ast.dump(node)
        return {'op':OPS[type(node.op)], 'left':walk(node.left), 'right':walk(node.right)}
    return walk(ast.parse(text, mode='eval').body)

def value(node):
    if isinstance(node, str): return rat(node)
    a,b = value(node['left']),value(node['right'])
    return {'add':lambda:a+b,'subtract':lambda:a-b,'multiply':lambda:a*b,'divide':lambda:a/b}[node['op']]()

def st(prompt, answer, explanation, hint=None):
    item = {'prompt':prompt, 'explanation':explanation}
    if answer is not None: item['answer'] = s(answer) if not isinstance(answer, str) or _numeric(answer) else answer
    if hint: item['hint'] = hint
    return item

def _numeric(v):
    try: rat(v); return True
    except (ValueError, ZeroDivisionError): return False

def add(n, slug, label, kind, answer, steps, **extra):
    exercise = EX.setdefault(n, {'number':n,'sourcePage':PAGES[n], 'coverage':{'sourceVerified':True,'subpartsComplete':True},'parts':[]})
    part = {'id':f'{n}-{slug}','label':label,'kind':kind,'answer':str(answer),'steps':steps,**extra}
    assert steps, (n,slug)
    assert not any(p['id']==part['id'] for p in exercise['parts']),part['id']
    exercise['parts'].append(part)
    return part

def num(n, slug, label, answer, steps, **extra):
    return add(n,slug,label,'numeric',s(answer),steps,**extra)

def expr(n, slug, label, text, **extra):
    node=tree(text); answer=s(value(node))
    return add(n,slug,label,'expression',answer,
      [st('Вычисли выражение, соблюдая скобки и порядок действий.',answer,
          'Выполняй действия в скобках, затем умножение и деление, затем сложение и вычитание. Дроби считай точно; итог: '+answer+'.')],
      expression=node,**extra)

def written(n,slug,label,answer,explanation,criteria=None,steps=None,**extra):
    return add(n,slug,label,'written',answer,
      steps or [st('Объясни решение.',None,explanation)], explanation=explanation,
      criteria=criteria or [answer,explanation],**extra)

def choice(n,slug,label,answer,explanation,choices=None,steps=None):
    return add(n,slug,label,'choice',answer,steps or [st('Сравни обе величины.',None,explanation)],
      choices=choices or ['Первая величина больше','Вторая величина больше','Величины равны'],explanation=explanation)

def pct(n,slug,label,percent,whole,unit=''):
    p=rat(percent); w=rat(whole); answer=p*w/100
    return num(n,slug,label,answer,[st('Запиши процент в виде доли.',p/100,f'{percent}% = {s(p/100)}.'),
      st('Умножь величину на найденную долю.',answer,f'{whole} · {s(p/100)} = {s(answer)} {unit}.')])

def whole(n,slug,label,part,percent,unit=''):
    a=rat(part); p=rat(percent); answer=a/(p/100)
    return num(n,slug,label,answer,[st('Запиши известный процент долей.',p/100,f'{percent}% = {s(p/100)}.'),
      st('Найди целую величину.',answer,f'{part} : {s(p/100)} = {s(answer)} {unit}.')])

def percent(n,slug,label,part,total,unit='%'):
    a=rat(part); b=rat(total); answer=a/b*100
    return num(n,slug,label,answer,[st('Найди отношение части к целому.',a/b,f'{part} : {total} = {s(a/b)}.'),
      st('Вырази отношение в процентах.',answer,f'{s(a/b)} · 100 = {s(answer)}{unit}.')])

def changed(n,slug,label,initial,pct_change):
    a=rat(initial); p=rat(pct_change)
    return num(n,slug,label,a*(1+p/100),[st('Найди величину изменения.',abs(a*p/100),f'{initial} · {s(abs(p)/100)} = {s(abs(a*p/100))}.'),
      st('Найди новую величину.',a*(1+p/100),f'{initial} '+('+' if p>=0 else '−')+f' {s(abs(a*p/100))} = {s(a*(1+p/100))}.')])

