    def spaced(item):
        if isinstance(item,list): return [spaced(v) for v in item]
        if isinstance(item,dict): return {k:spaced(v) for k,v in item.items()}
        if isinstance(item,str):
            return re.sub(r'(\d)([А-Яа-яЁё])',r'\1 \2',re.sub(r'([А-Яа-яЁё])(\d)',r'\1 \2',item))
